source='''def transform(grid):
    """Fill gaps between repeated non-background markers in each row and column."""
    out = [row[:] for row in grid]
    vals = {v for row in grid for v in row}
    if len(vals) < 2:
        return out
    # ARC examples use the most common value as background and the other as marker.
    counts = {v: sum(cell == v for row in grid for cell in row) for v in vals}
    bg = max(vals, key=lambda v: counts[v])
    marker = next(v for v in vals if v != bg)
    h, w = len(grid), len(grid[0])
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 2:
            for r in range(min(rows) + 1, max(rows)):
                if grid[r][c] == bg:
                    out[r][c] = 3
    return out
'''
